class Inspect(HTMLParser):
 def __init__(self):super().__init__(convert_charrefs=True);self.ids=[];self.links=[];self.pre={};self.active=None
 def handle_starttag(self,t,attrs):
  a=dict(attrs)
  if'id'in a:self.ids.append(a['id'])
  if t=='a'and'href'in a:self.links.append(a['href'])
  if t=='pre'and a.get('id','').startswith('source-code-'):self.active=a['id'];self.pre[self.active]=''
 def handle_data(self,s):
  if self.active:self.pre[self.active]+=s
 def handle_endtag(self,t):
  if t=='pre':self.active=None
